WITH parsed AS (SELECT id, effective_from, currency, tier_prices, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ELEMENT_AT(tier_prices, 1) AS entry_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ARRAY_MIN(tier_prices) AS lowest_price FROM price_tiers) SELECT *, AVG(avg_tier_price) OVER (PARTITION BY currency ORDER BY lowest_price, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS avg_tier_price_avg_2, SUM(avg_tier_price) OVER w_part AS running_avg_tier_price, FIRST_VALUE(lowest_price) IGNORE NULLS OVER w_part AS first_known_lowest_price, RANK() OVER (PARTITION BY currency ORDER BY lowest_price DESC) AS lowest_price_rank FROM parsed WINDOW w_part AS (PARTITION BY currency ORDER BY lowest_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
